create or replace function public.record_business_engagement_attribution(p_business_id uuid default null,p_location_id uuid default null,p_partner_network_id uuid default null,p_campaign_id uuid default null,p_activity_type text default 'engagement',p_source text default 'consumer',p_metadata jsonb default '{}'::jsonb) returns public.business_engagement_attributions language plpgsql security definer set search_path=public as $function$ declare a public.business_engagement_attributions; v_business uuid; v_network uuid; begin if auth.uid() is null then raise exception 'authentication required'; end if; if p_location_id is not null then select business_id into v_business from public.locations where id=p_location_id; if v_business is null then raise exception 'location not found'; end if; if p_business_id is not null and p_business_id<>v_business then raise exception 'location/business mismatch'; end if; else v_business:=p_business_id; end if; if p_campaign_id is not null then select network_id into v_network from public.enterprise_partner_campaigns where id=p_campaign_id; if v_network is null then raise exception 'campaign not found'; end if; if p_partner_network_id is not null and p_partner_network_id<>v_network then raise exception 'campaign/network mismatch'; end if; end if; if v_business is not null then p_business_id:=v_business; end if; if v_network is not null then p_partner_network_id:=v_network; end if; insert into public.business_engagement_attributions(user_id,business_id,location_id,partner_network_id,campaign_id,activity_type,source,metadata) values(auth.uid(),p_business_id,p_location_id,p_partner_network_id,p_campaign_id,p_activity_type,p_source,coalesce(p_metadata,'{}'::jsonb)) returning * into a; return a; end $function$; create or replace function public.record_progression_metric_event(p_metric text,p_source_type text,p_source_id uuid default null,p_quantity numeric default 1,p_points_awarded integer default null,p_metadata jsonb default '{}'::jsonb) returns public.progression_metric_events language plpgsql security definer set search_path=public as $function$ declare v_row public.progression_metric_events; v_action_points integer; v_enabled boolean; v_points integer:=0; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select points,enabled into v_action_points,v_enabled from public.progression_actions where code=trim(p_metric) limit 1; if coalesce(v_enabled,false) then v_points:=greatest(coalesce(v_action_points,0)*greatest(p_quantity,0)::integer,0); if p_source_id is not null then perform public.record_gamification_activity(trim(p_metric),p_source_id); end if; else v_points:=0; end if; insert into public.progression_metric_events(user_id,metric,source_type,source_id,quantity,points_awarded,metadata) values(auth.uid(),trim(p_metric),p_source_type,p_source_id,greatest(p_quantity,0),v_points,coalesce(p_metadata,'{}'::jsonb)) returning * into v_row; return v_row; end $function$;
